class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        # Convert MiB to bytes (1 MiB = 1024 * 1024 bytes)
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # month -> {name: size_bytes} for files that count toward quota
        self._files: dict[str, dict[str, int]] = {}
        # month -> total bytes counted toward quota
        self._used: dict[str, int] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like "2026-01"."""
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0")

        files_this_month = self._files.setdefault(month, {})
        used_this_month = self._used.setdefault(month, 0)

        # Uploading again a file with the same name in the same month
        # does not count towards the limit a second time.
        if name in files_this_month:
            return

        # Would exceed the monthly limit?
        if used_this_month + size_bytes > self._limit_bytes:
            raise ValueError(
                f"Upload would exceed monthly limit of {self._limit_bytes} bytes"
            )

        files_this_month[name] = size_bytes
        self._used[month] = used_this_month + size_bytes

    def delete(self, name: str, month: str) -> None:
        # Deleting a file does not give back quota in the current month.
        files_this_month = self._files.get(month)
        if files_this_month is not None:
            files_this_month.pop(name, None)

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return self._used.get(month, 0)
```

### Notes on behavior

- **Re-upload in same month:** If the name already exists in `_files[month]`, `upload` returns without adding to `_used`. The original size remains counted.
- **Zero-size uploads:** Raises `ValueError` before any state mutation.
- **Limit enforcement:** The check `used + size > limit` is performed against the running total; on failure, no state is changed.
- **Deletion:** `delete` removes the name from the bookkeeping so re-uploading later would count again, but it deliberately leaves `_used[month]` untouched, so deleted bytes still consume quota for that month.
- **Month isolation:** Quota is tracked per month string (e.g., `"2026-01"`), so each month has an independent limit.

